def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([5, 5]), fmt([1, 2]), fmt([-3, -3, -3, -3]), fmt([1, 2, 2]), fmt([2, 1, 2, 1])]
    for n in range(1, 9):
        for _ in range(2):
            tests.append(fmt([rng.randint(-3, 3) for _ in range(n)]))
    for n in (4, 6, 7):
        tests.append(fmt(rng.sample(range(-10, 11), n)))
    tests.append(fmt(rng.sample(range(-10, 11), 14)))
    tests.append(fmt([rng.randint(-2, 2) for _ in range(14)]))
    tests.append(fmt([7] * 14))
    tests.append(fmt([rng.randint(-10, 10) for _ in range(14)]))
    return tests
